<?php
declare(strict_types=1);use Acorn\SafetyHealthcheck\Assessment\{CompletionService,AssessmentRepository};use Acorn\SafetyHealthcheck\Privacy\ExportEraser;
final class PrivacyTest extends IntegrationTestCase{public function test_export_and_erasure_remove_pii_and_revoke_report():void{[$s,$token]=$this->assessed();$done=(new CompletionService)->complete($token,['first_name'=>'Ada','last_name'=>'Lovelace','company'=>'Analytical','email'=>'privacy@example.test','audit_requested'=>false]);$privacy=new ExportEraser();self::assertNotEmpty($privacy->export('privacy@example.test')['data']);$privacy->erase('privacy@example.test');$row=(new AssessmentRepository)->find($done['assessment_id']);self::assertNull($row['report_token_hash']);self::assertStringContainsString('Removed following privacy request',$row['snapshot_json']);}}
